css:
/* Logo carousel: a centred heading over a scroll-snap rail of logos, seven in view on a wide screen.
   Arrows sit at the ends of the rail; the rail also scrolls by touch, wheel and arrow keys. */
[data-bz-node="logos"] > .bz-container { max-width: calc(min(90vw, 1440px) + 32px); }
[data-bz-section="logo-carousel"] .bz-block { padding-block: 0; }
[data-bz-section="logo-carousel"] h2 { margin: 0; text-align: center; font: 700 1.5rem / 1.2 var(--font-heading); color: #000; letter-spacing: 0; }
[data-bz-section="logo-carousel"] [data-bz-node="logos-rail"] { --bz-slide-gap: 0px; margin-top: 56px; display: flex; gap: 0; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none; padding: 0; }
[data-bz-section="logo-carousel"] [data-bz-node="logos-rail"]::-webkit-scrollbar { display: none; }
[data-bz-section="logo-carousel"] [data-bz-node="logos-rail"] > .bz-col { flex: 0 0 calc(100% / 7); grid-column: auto; scroll-snap-align: start; min-width: 0; display: flex; align-items: center; justify-content: center; height: 150px; }
[data-bz-section="logo-carousel"] .bz-figure { margin: 0; display: flex; align-items: center; justify-content: center; }
[data-bz-section="logo-carousel"] .bz-figure img { display: block; width: auto; max-width: 150px; max-height: 150px; height: auto; border-radius: 0; }
[data-bz-section="logo-carousel"] [data-bz-node="logos-wrap"] { position: relative; }
[data-bz-section="logo-carousel"] [data-bz-node="logos-prev"], [data-bz-section="logo-carousel"] [data-bz-node="logos-next"] { position: absolute; z-index: 2; top: 50%; width: 40px; height: 40px; margin-top: -20px; padding: 0; }
[data-bz-section="logo-carousel"] [data-bz-node="logos-prev"] { left: 0; } [data-bz-section="logo-carousel"] [data-bz-node="logos-next"] { right: 0; }
[data-bz-section="logo-carousel"] [data-bz-node="logos-prev"] .bz-container, [data-bz-section="logo-carousel"] [data-bz-node="logos-next"] .bz-container { padding: 0; }
[data-bz-section="logo-carousel"] [data-bz-node="logos-prev"] .bz-text p, [data-bz-section="logo-carousel"] [data-bz-node="logos-next"] .bz-text p { margin: 0; width: 40px; height: 40px; border-radius: 50%; background: #fff; box-shadow: 0 1px 6px rgba(0, 0, 0, 0.25); color: var(--accent); font: 700 1.6rem / 38px var(--font-body); text-align: center; cursor: pointer; }
[data-bz-section="logo-carousel"] [data-bz-carousel][data-bz-at-start] [data-bz-node="logos-prev"], [data-bz-section="logo-carousel"] [data-bz-carousel][data-bz-at-end] [data-bz-node="logos-next"] { opacity: 0.35; }
@media (max-width: 1100px) { [data-bz-section="logo-carousel"] [data-bz-node="logos-rail"] > .bz-col { flex-basis: 25%; } }
@media (max-width: 640px) { [data-bz-section="logo-carousel"] [data-bz-node="logos-rail"] > .bz-col { flex-basis: 50%; } [data-bz-section="logo-carousel"] h2 { font-size: 1.3rem; } }
